insert into sections (id,eyebrow,title,description,extra) values ('about','About the chapter','A home for Chemical Engineering students at Kuwait University.',null,'{"paragraphs":["The AIChE Kuwait University Student Chapter is run by students, for students. We bring Chemical Engineering students together through workshops, industrial visits, competitions and volunteering, and connect them with the wider AIChE community.","Whether you are in your first year or about to graduate, the chapter is a place to build skills, meet people and get closer to industry."]}'::jsonb) on conflict do nothing;
